create role authenticated;
create role anon;
create schema auth;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
grant usage on schema auth to authenticated,anon;
grant execute on function auth.uid() to authenticated,anon;
create table public.profiles(id uuid primary key);
create table public.organizations(user_id uuid primary key references public.profiles(id),profile jsonb not null default '{}',updated_at timestamptz not null default now());
create table public.organization_memberships(org_id uuid references public.organizations(user_id),member_id uuid references public.profiles(id),role text,primary key(org_id,member_id));
create table public.accelerator_purchases(id uuid default gen_random_uuid(),user_id uuid,status text);
create table public.subscriptions(id uuid default gen_random_uuid(),user_id uuid,status text,metadata jsonb,stripe_subscription_id text,created_at timestamptz default now());
create table public.classes(id uuid primary key,is_published boolean not null);
create table public.modules(id uuid primary key,class_id uuid references public.classes(id),is_published boolean not null);
create table public.module_assignments(module_id uuid primary key references public.modules(id),schema jsonb,complete_on_submit boolean,updated_at timestamptz not null default now());
create table public.assignment_submissions(module_id uuid references public.modules(id),user_id uuid references public.profiles(id),answers jsonb not null default '{}',status text,updated_at timestamptz not null default now(),primary key(module_id,user_id));
create table public.module_progress(module_id uuid references public.modules(id),user_id uuid references public.profiles(id),status text,completed_at timestamptz,updated_at timestamptz default now(),primary key(user_id,module_id));
alter table public.assignment_submissions enable row level security;
alter table public.module_progress enable row level security;
alter table public.organizations enable row level security;
create policy own_submissions on public.assignment_submissions for select to authenticated using(user_id=auth.uid());
create policy own_progress on public.module_progress for select to authenticated using(user_id=auth.uid());
create policy own_organization on public.organizations for select to authenticated using(user_id=auth.uid());
grant select on public.assignment_submissions,public.module_progress,public.organizations to authenticated;
